// Replays every case file in /workspace/dev/cases/scanner-parser through the executable
// and prints a byte-exact record.
const { spawnSync } = require("child_process");
const fs = require("fs");
const path = require("path");
const dir = "/workspace/dev/cases/scanner-parser";
const files = fs.readdirSync(dir).sort();
const vis = s => s
  .replace(/\r/g, "<CR>")
  .replace(/\t/g, "<TAB>")
  .replace(//g, "<NEL>")
  .replace(/ /g, "<LS>")
  .replace(/ /g, "<PS>")
  .replace(/﻿/g, "<BOM>")
  .replace(/ /g, "<NBSP>")
  .replace(/[�-  --￾￿]/g,
           c => "<x" + c.charCodeAt(0).toString(16).padStart(2, "0") + ">")
  .replace(/ /g, "·")
  .replace(/\n/g, "$\n");
let ok = 0, err = 0;
for (const f of files) {
  const v = fs.readFileSync(path.join(dir, f), "utf8");
  const r = spawnSync("/workspace/dataset/test9_executable", ["--a", v], { encoding: "utf8" });
  console.log("##### " + f);
  console.log("IN:\n" + vis(v) + (v.endsWith("\n") ? "" : "<noNL>") + "\n");
  console.log("RC=" + r.status);
  if (r.status === 0) { ok++; console.log("OUT:\n" + vis(r.stdout)); }
  else {
    err++;
    const L = r.stderr.split("\n").filter(x => x.length);
    // the exception class + message (skip traceback frames, skip PYI line)
    const idx = L.findIndex(x => /^yaml\.[a-z]+\.[A-Za-z]+Error/.test(x));
    console.log("ERRCLASS=" + (idx >= 0 ? L[idx].split(":")[0] : "?"));
    console.log("ERR:\n" + L.slice(idx >= 0 ? idx : 0).filter(x => !/^\[PYI-/.test(x)).join("\n"));
  }
  console.log("");
}
console.error("ok=" + ok + " err=" + err + " total=" + files.length);

// Replays every case file in /workspace/dev/cases/scanner-parser through the executable
// and prints a byte-exact record.
const { spawnSync } = require("child_process");
const fs = require("fs");
const path = require("path");
const dir = "/workspace/dev/cases/scanner-parser";
const files = fs.readdirSync(dir).sort();
function vis(s) {
  let o = "";
  for (const ch of s) {
    const c = ch.codePointAt(0);
    if (ch === "\n") o += "$\n";
    else if (ch === "\r") o += "<CR>";
    else if (ch === "\t") o += "<TAB>";
    else if (ch === " ") o += "·";
    else if (c === 0x85) o += "<NEL>";
    else if (c === 0x2028) o += "<LS>";
    else if (c === 0x2029) o += "<PS>";
    else if (c === 0xFEFF) o += "<BOM>";
    else if (c === 0xA0) o += "<NBSP>";
    else if (c < 0x20 || c === 0x7f || (c >= 0x80 && c <= 0x9f) || c === 0xfffe || c === 0xffff)
      o += "<x" + c.toString(16).padStart(2, "0") + ">";
    else o += ch;
  }
  return o;
}
let ok = 0, err = 0;
for (const f of files) {
  const v = fs.readFileSync(path.join(dir, f), "utf8");
  const r = spawnSync("/workspace/dataset/test9_executable", ["--a", v], { encoding: "utf8" });
  console.log("##### " + f);
  console.log("IN:\n" + vis(v) + (v.endsWith("\n") ? "" : "<noNL>") + "\n");
  console.log("RC=" + r.status);
  if (r.status === 0) { ok++; console.log("OUT:\n" + vis(r.stdout)); }
  else {
    err++;
    const L = r.stderr.split("\n").filter(x => x.length);
    const idx = L.findIndex(x => /^yaml\.[a-z]+\.[A-Za-z]+Error/.test(x));
    console.log("ERR:\n" + L.slice(idx >= 0 ? idx : 0).filter(x => !/^\[PYI-/.test(x)).join("\n"));
  }
  console.log("");
}
console.error("ok=" + ok + " err=" + err + " total=" + files.length);

